/// A non-empty CHILD selector using ONLY selector-safe characters (mirrors `SAFE_SELECTOR`).
pub(crate) fn is_safe_selector(s: &str) -> bool {
    !s.is_empty()
        && s.chars().all(|c| {
            c.is_ascii_alphanumeric()
                || matches!(
                    c,
                    ' ' | '.' | '_' | '#' | '>' | '[' | ']' | '=' | '"' | '\'' | '-' | ':' | '(' | ')'
                        | ',' | '*' | '+' | '~'
                )
        })
}
